text:
{
  "units": {
    "s001": {
      "claims": [
        {
          "claim": "辅修学士学位与微专业修读证书不能视为同一种学位成果",
          "evidence_sentence_ids": [
            "b1_s016"
          ],
          "score": 5,
          "verdict": "supported"
        },
        {
          "claim": "二者在性质、授予条件、证书效力和学位归属等方面存在本质差别",
          "evidence_sentence_ids": [],
          "score": 2,
          "verdict": "unsupported"
        }
      ],
      "non_factual_reason": "性质、条件、效力等差异未在证据中具体陈述，仅由答案推导，缺乏直接支持"
    },
    "s002": {
      "claims": [
        {
          "claim": "辅修学士学位属于学位层次",
          "evidence_sentence_ids": [],
          "score": 2,
          "verdict": "unsupported"
        },
        {
          "claim": "辅修学士学位是学生在主修专业之外，通过修读辅修专业并达到规定学分和学术要求后，经学校批准授予的正式学位",
          "evidence_sentence_ids": [
            "b1_s015"
          ],
          "score": 4,
          "verdict": "partially_supported"
        },
        {
          "claim": "其学位在主修学士学位证书中予以注明，不单独颁发学位证书",
          "evidence_sentence_ids": [
            "b1_s016"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": "‘学位层次’无证据支持，‘正式学位’由上下文推导，但未明确‘学位层次’定义"
    },
    "s003": {
      "claims": [
        {
          "claim": "辅修学士学位的授予需满足主修专业毕业要求",
          "evidence_sentence_ids": [
            "b1_s015"
          ],
          "score": 4,
          "verdict": "partially_supported"
        },
        {
          "claim": "需符合辅修专业人才培养方案中关于学分和学术能力的要求",
          "evidence_sentence_ids": [
            "b1_s015"
          ],
          "score": 4,
          "verdict": "partially_supported"
        },
        {
          "claim": "在主修专业毕业证书中明确标注，具有正式学位资格，属于学位体系的一部分",
          "evidence_sentence_ids": [
            "b1_s016"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘正式学位资格’‘属于学位体系’为推论，无直接证据"
    },
    "s004": {
      "claims": [
        {
          "claim": "微专业修读证书仅是课程修读成果的证明，不授予学位",
          "evidence_sentence_ids": [
            "b1_s019"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    },
    "s005": {
      "claims": [
        {
          "claim": "微专业是围绕特定领域设置的模块化课程群，旨在提升学生的跨学科知识和实践能力",
          "evidence_sentence_ids": [
            "b4_s008"
          ],
          "score": 4,
          "verdict": "partially_supported"
        },
        {
          "claim": "其修读不涉及学位授予，学生修满规定学分后可申请获得微专业修读证书，但该证书仅为学习成果证明，不具备学位属性",
          "evidence_sentence_ids": [
            "b1_s019",
            "b3_s014"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": "‘提升跨学科知识和实践能力’为政策目标，非直接陈述"
    },
    "s006": {
      "claims": [
        {
          "claim": "辅修学士学位的授予需经过学位评定委员会审核",
          "evidence_sentence_ids": [],
          "score": 2,
          "verdict": "unsupported"
        },
        {
          "claim": "微专业修读证书由牵头学院审核并报教务处审批后颁发，属于非学位类证书",
          "evidence_sentence_ids": [
            "b3_s016"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘学位评定委员会审核’无证据，‘非学位类证书’由流程推导"
    },
    "s007": {
      "claims": [
        {
          "claim": "辅修学士学位是正式的学位成果，具有法律效力和学位等级",
          "evidence_sentence_ids": [],
          "score": 2,
          "verdict": "unsupported"
        },
        {
          "claim": "微专业修读证书仅为课程修读证明，不具备学位属性，两者在性质和学术地位上完全不同",
          "evidence_sentence_ids": [
            "b1_s019",
            "b3_s014"
          ],
          "score": 4,
          "verdict": "partially_supported"
        }
      ],
      "non_factual_reason": "‘法律效力’‘学位等级’无证据支持"
    },
    "s008": {
      "claims": [
        {
          "claim": "参考文献[1][3]对应证据",
          "evidence_sentence_ids": [
            "b1_s016",
            "b1_s019"
          ],
          "score": 5,
          "verdict": "supported"
        }
      ],
      "non_factual_reason": ""
    }
  }
}
